# Try simple same-size transformations of the upper object relative to lower and summarize overlap.
import numpy as np
um=np.array(upper)==7; lm=np.array(lower)==7
variants={'orig':um,'hflip':um[:,::-1],'vflip':um[::-1,:],'rot180':um[::-1,::-1]}
for name,m in variants.items():
    scores=[]
    for dx in range(-23,24):
        shifted={(r,c+dx) for r in range(2) for c in range(24) if m[r,c] and 0<=c+dx<24}
        overlap=len(shifted & L); extras=len(L-shifted); missing=len(shifted-L)
        scores.append((overlap,-extras,-missing,dx))
    print(name,max(scores))
